import java.util.*;

class Solution {
    private static class TrieNode {
        TrieNode[] children = new TrieNode[26];
        String word;
    }

    private final int[][] dirs = new int[][] {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    public List<String> findWords(char[][] board, String[] words) {
        TrieNode root = new TrieNode();
        for (String word : words) {
            insert(root, word);
        }

        List<String> result = new ArrayList<>();
        for (int r = 0; r < board.length; r++) {
            for (int c = 0; c < board[0].length; c++) {
                dfs(board, r, c, root, result);
            }
        }
        Collections.sort(result);
        return result;
    }

    private void insert(TrieNode root, String word) {
        TrieNode node = root;
        for (char c : word.toCharArray()) {
            int idx = c - 'a';
            if (node.children[idx] == null) {
                node.children[idx] = new TrieNode();
            }
            node = node.children[idx];
        }
        node.word = word;
    }

    private void dfs(char[][] board, int r, int c, TrieNode node, List<String> result) {
        if (r < 0 || r >= board.length || c < 0 || c >= board[0].length) {
            return;
        }
        char ch = board[r][c];
        if (ch == '#') {
            return;
        }
        TrieNode next = node.children[ch - 'a'];
        if (next == null) {
            return;
        }

        if (next.word != null) {
            result.add(next.word);
            next.word = null;
        }

        board[r][c] = '#';
        for (int[] dir : dirs) {
            dfs(board, r + dir[0], c + dir[1], next, result);
        }
        board[r][c] = ch;
    }
}

import java.util.*;

class Solution {
    private static class TrieNode {
        TrieNode[] children = new TrieNode[26];
        String word;
        int childCount;
    }

    private final int[][] dirs = new int[][] {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    public List<String> findWords(char[][] board, String[] words) {
        TrieNode root = new TrieNode();
        for (String word : words) {
            add(root, word);
        }

        List<String> result = new ArrayList<>();
        for (int r = 0; r < board.length; r++) {
            for (int c = 0; c < board[0].length; c++) {
                dfs(board, r, c, root, result);
            }
        }
        Collections.sort(result);
        return result;
    }

    private void add(TrieNode root, String word) {
        TrieNode node = root;
        for (char c : word.toCharArray()) {
            int idx = c - 'a';
            if (node.children[idx] == null) {
                node.children[idx] = new TrieNode();
                node.childCount++;
            }
            node = node.children[idx];
        }
        node.word = word;
    }

    private void dfs(char[][] board, int r, int c, TrieNode parent, List<String> result) {
        if (r < 0 || r >= board.length || c < 0 || c >= board[0].length) {
            return;
        }
        char ch = board[r][c];
        if (ch == '#') {
            return;
        }
        int idx = ch - 'a';
        TrieNode node = parent.children[idx];
        if (node == null) {
            return;
        }

        if (node.word != null) {
            result.add(node.word);
            node.word = null;
        }

        board[r][c] = '#';
        for (int[] dir : dirs) {
            dfs(board, r + dir[0], c + dir[1], node, result);
        }
        board[r][c] = ch;

        if (node.word == null && node.childCount == 0) {
            parent.children[idx] = null;
            parent.childCount--;
        }
    }
}

import java.util.*;

class Solution {
    private final int[][] dirs = new int[][] {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    public List<String> findWords(char[][] board, String[] words) {
        List<String> result = new ArrayList<>();
        for (String word : words) {
            if (exists(board, word)) {
                result.add(word);
            }
        }
        Collections.sort(result);
        return result;
    }

    private boolean exists(char[][] board, String word) {
        boolean[][] visited = new boolean[board.length][board[0].length];
        for (int r = 0; r < board.length; r++) {
            for (int c = 0; c < board[0].length; c++) {
                if (dfs(board, word, 0, r, c, visited)) {
                    return true;
                }
            }
        }
        return false;
    }

    private boolean dfs(char[][] board, String word, int index, int r, int c, boolean[][] visited) {
        if (index == word.length()) {
            return true;
        }
        if (r < 0 || r >= board.length || c < 0 || c >= board[0].length) {
            return false;
        }
        if (visited[r][c] || board[r][c] != word.charAt(index)) {
            return false;
        }

        visited[r][c] = true;
        for (int[] dir : dirs) {
            if (dfs(board, word, index + 1, r + dir[0], c + dir[1], visited)) {
                visited[r][c] = false;
                return true;
            }
        }
        visited[r][c] = false;
        return false;
    }
}

import java.util.*;

class Solution {
    private final int[][] dirs = new int[][] {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};
    private int rows;
    private int cols;
    private int maxLen;

    public List<String> findWords(char[][] board, String[] words) {
        Set<String> dictionary = new HashSet<>();
        Set<String> prefixes = new HashSet<>();
        maxLen = 0;
        for (String word : words) {
            dictionary.add(word);
            maxLen = Math.max(maxLen, word.length());
            for (int i = 1; i <= word.length(); i++) {
                prefixes.add(word.substring(0, i));
            }
        }

        rows = board.length;
        cols = board[0].length;
        boolean[][] visited = new boolean[rows][cols];
        Set<String> found = new HashSet<>();
        StringBuilder path = new StringBuilder();

        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                dfs(board, r, c, visited, path, prefixes, dictionary, found);
            }
        }

        List<String> result = new ArrayList<>(found);
        Collections.sort(result);
        return result;
    }

    private void dfs(char[][] board, int r, int c, boolean[][] visited, StringBuilder path,
                     Set<String> prefixes, Set<String> dictionary, Set<String> found) {
        if (r < 0 || r >= rows || c < 0 || c >= cols || visited[r][c]) {
            return;
        }

        path.append(board[r][c]);
        String current = path.toString();
        if (!prefixes.contains(current)) {
            path.deleteCharAt(path.length() - 1);
            return;
        }

        if (dictionary.contains(current)) {
            found.add(current);
        }

        if (current.length() < maxLen) {
            visited[r][c] = true;
            for (int[] dir : dirs) {
                dfs(board, r + dir[0], c + dir[1], visited, path, prefixes, dictionary, found);
            }
            visited[r][c] = false;
        }
        path.deleteCharAt(path.length() - 1);
    }
}
